<script lang="ts">
 import{onDestroy}from'svelte';
 import{MAX_PROFILE_BYTES,type ProfileDocument,type ProfileSummary,type DeepReadonly}from'./profiles';
 import{savedProfileTarget,deleteSavedProfile,importSavedProfile,exportSavedProfile,profileExportFilename,profileImportNameError,type ProfileLibraryClient,type SavedProfileTarget}from'./profile-library';
 let{client,profileCount,readOnly,busy=false,prepare,resolveProfile,onDeleted,onImported,onBusy=()=>{}}:{client:ProfileLibraryClient;profileCount:number;readOnly:boolean;busy?:boolean;prepare:(next:()=>void)=>void;resolveProfile:(id:string)=>DeepReadonly<ProfileSummary>|undefined;onDeleted:()=>Promise<void>;onImported:(document:ProfileDocument)=>Promise<void>;onBusy?:(busy:boolean)=>void}=$props();
 let mode=$state<'delete'|'import'|'export'|null>(null),target=$state<Readonly<SavedProfileTarget>|null>(null),pending=$state(false),source=$state(''),name=$state('Imported profile'),error=$state(''),exported=$state(''),exportName=$state('profile');
 let epoch=0,disposed=false;
 onDestroy(()=>{disposed=true;epoch++;});
 function show(node:HTMLDialogElement){node.showModal();return()=>node.close();}
 function close(){if(pending)return;epoch++;mode=null;target=null;error='';exported='';source='';}
 export function askDelete(value:DeepReadonly<ProfileSummary>){if(readOnly||busy||pending||value.isDefault)return;const captured=savedProfileTarget(value);prepare(()=>{const current=resolveProfile(captured.id);target=current?savedProfileTarget(current):null;mode='delete';error=current?'':'This saved profile changed or was removed. Refresh the library before deleting.';});}
 export function askImport(){if(readOnly||busy||pending)return;prepare(()=>{target=null;mode='import';source='';name='Imported profile';error='';});}
 export async function askExport(value:DeepReadonly<ProfileSummary>){if(busy||pending)return;target=savedProfileTarget(value);mode='export';exported='';error='';const captured=target,ticket=++epoch;pending=true;onBusy(true);try{const result=await exportSavedProfile(client,captured);if(disposed||ticket!==epoch)return;exported=result.text;exportName=result.document.name;}catch(value){if(!disposed&&ticket===epoch)error=String(value instanceof Error?value.message:value);}finally{if(!disposed&&ticket===epoch){pending=false;onBusy(false);}}}
 async function remove(){if(mode!=='delete'||!target||pending||busy||readOnly)return;const captured=target,ticket=++epoch;pending=true;onBusy(true);error='';try{await deleteSavedProfile(client,captured,readOnly);if(disposed||ticket!==epoch)return;await onDeleted();if(disposed||ticket!==epoch)return;pending=false;mode=null;}catch(value){if(!disposed&&ticket===epoch)error=String(value instanceof Error?value.message:value);}finally{if(!disposed&&ticket===epoch){pending=false;onBusy(false);}}}
 async function importProfile(){if(mode!=='import'||pending||busy||readOnly)return;const ticket=++epoch,text=source,label=name;pending=true;onBusy(true);error='';try{const document=await importSavedProfile(client,text,label,profileCount,readOnly);if(disposed||ticket!==epoch)return;await onImported(document);if(disposed||ticket!==epoch)return;pending=false;mode=null;}catch(value){if(!disposed&&ticket===epoch)error=String(value instanceof Error?value.message:value);}finally{if(!disposed&&ticket===epoch){pending=false;onBusy(false);}}}
 async function file(event:Event){const input=event.currentTarget as HTMLInputElement,selected=input.files?.[0];if(!selected||pending)return;const ticket=++epoch,before=source;error='';try{if(selected.size>MAX_PROFILE_BYTES)throw Error('Portable profiles are limited to 512 KiB.');const text=await selected.text();if(!disposed&&ticket===epoch&&mode==='import'&&source===before)source=text;}catch(value){if(!disposed&&ticket===epoch)error=String(value instanceof Error?value.message:value);}finally{input.value='';}}
 function download(){if(!exported||pending)return;const url=URL.createObjectURL(new Blob([exported],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=profileExportFilename(exportName);link.click();window.setTimeout(()=>URL.revokeObjectURL(url),0);}
</script>
{#if mode}
 <dialog class="library-dialog" role="alertdialog" aria-modal="true" aria-labelledby="profile-library-title" oncancel={event=>{event.preventDefault();close();}} onclose={close} {@attach show}>
  <h2 id="profile-library-title">{mode==='delete'?`Delete ${target?.name}?`:mode==='import'?'Import portable profile':'Export saved profile'}</h2>
  {#if mode==='delete'}<p>Delete this profile and its local resource assignments. This cannot be undone. An active profile remains active until deactivated.</p>
  {:else if mode==='import'}<p>Import creates an independent saved profile with a fresh identity and no machine assignments. Choose resources explicitly after importing. It does not activate the profile.</p><label>New profile name<input class="text-input" bind:value={name} maxlength="80" disabled={pending}/></label><label>Portable profile file<input type="file" accept="application/json,.json" onchange={file} disabled={pending}/></label><label>Portable profile JSON<textarea class="text-input" bind:value={source} rows="10" spellcheck="false" disabled={pending}></textarea></label><p>Maximum 512 KiB · {profileCount} of 32 saved profiles used.</p>
  {:else}<p>This is the saved portable profile. Unsaved editor changes, local device assignments, credentials and backend slots are excluded.</p>{#if pending}<p role="status">Reading saved profile…</p>{/if}{#if exported}<label>Exported profile JSON<textarea class="text-input" value={exported} rows="12" readonly spellcheck="false"></textarea></label><button class="secondary-button" onclick={download}>Download profile JSON</button>{/if}{/if}
  {#if error}<p class="library-error" role="alert">{error} No operation is retried automatically.</p>{/if}
  <div class="library-actions"><button class="secondary-button" disabled={pending} onclick={close}>{mode==='delete'?'Keep profile':'Close'}</button>{#if mode==='delete'}<button class="primary-button" disabled={pending||busy||readOnly||!target} onclick={remove}>{pending?'Deleting…':'Delete saved profile'}</button>{:else if mode==='import'}<button class="primary-button" disabled={pending||busy||readOnly||profileCount>=32||!source.trim()||!!profileImportNameError(name)} onclick={importProfile}>{pending?'Importing…':'Import as new profile'}</button>{/if}</div>
 </dialog>
{/if}
<style>
 .library-dialog{position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);width:calc(100% - 40px);max-width:650px;max-height:85vh;overflow:auto;padding:26px;margin:0;border:1px solid var(--line);border-radius:10px;background:var(--surface);color:var(--text);box-shadow:0 20px 80px #0005}.library-dialog::backdrop{background:#0009}.library-dialog h2{font-size:17px}.library-dialog p{font-size:11px;color:var(--muted);line-height:1.8;margin:15px 0}.library-dialog label{display:grid;gap:8px;font-size:11px;margin:14px 0;color:var(--soft)}.library-dialog textarea{font-family:monospace;font-size:10px;min-width:0;width:100%;resize:vertical}.library-dialog input{min-width:0;width:100%}.library-dialog button{font-size:11px}.library-actions{display:flex;justify-content:end;gap:10px;flex-wrap:wrap;margin-top:22px}.library-dialog .library-error{color:#d3a078}
</style>
